parts.openscad_module:
$fn = 64;

servo_l    = 40.5;
servo_w    = 20.5;
servo_h    = 44;
tab_span   = 49;
hole_d     = 3.4;
bracket_t  = 4;
clearance  = 0.5;

plate_l    = tab_span + 10;

module mg996r_bracket() {
  difference() {
    union() {
      cube([plate_l, servo_w + 2*bracket_t, bracket_t], center = true);
      for (s = [-1, 1])
        translate([0, s * (servo_w/2 + bracket_t/2), servo_h/2])
          cube([plate_l, bracket_t, servo_h], center = true);
    }
    cube([servo_l + clearance, servo_w + clearance + 2, servo_h + clearance], center = true);
    for (x = [-tab_span/2, tab_span/2])
      translate([x, 0, 0])
        rotate([90, 0, 0])
          cylinder(h = servo_w + 2*bracket_t + 2, d = hole_d, center = true, $fn = 32);
  }
}

mg996r_bracket();
